#!/usr/bin/env python3
"""Render inventory JSON as the per-model feature checklist (Markdown).

    inventory_report.py <models.tsv> <inventory_dir> <out.md>

models.tsv: model<TAB>inventory json<TAB>sheet name<TAB>socs
"""
import json
import os
import sys


def esc(s):
    return str(s).replace("|", "\\|").replace("\n", " ")


models_tsv, inv_dir, out = sys.argv[1:4]
lines = ["# Spreadsheet feature checklist", "",
         "Generated by tools/inventory_report.py from inventory/*.json. Every input,",
         "option and formula cell below must have a counterpart in the tool; the",
         "coverage test enforces it.", ""]
for row in open(models_tsv, encoding="utf-8"):
    if not row.strip() or row.startswith("#"):
        continue
    model, inv, sheet_name, socs = row.rstrip("\n").split("\t")
    book = json.load(open(os.path.join(inv_dir, inv), encoding="utf-8"))
    sh = book["sheets"][sheet_name]
    lines += [f"## {model} ({socs})", "", f"Source: `{book['workbook']}` sheet `{sheet_name.strip()}`, "
              f"{len(sh['inputs'])} inputs, {len(sh['formulas'])} formulas.", "",
              "| cell | row label | column label | default | options |", "|---|---|---|---|---|"]
    for ref, i in sh["inputs"].items():
        opts = ", ".join(esc(o) for o in (i.get("options") or []))
        lines.append(f"| {ref} | {esc(i['label']['row'] or '')} | {esc(i['label']['col'] or '')} | "
                     f"{esc(i['value'])} | {opts} |")
    lines += ["", "<details><summary>formula cells</summary>", "",
              "| cell | row label | column label | cached | formula |", "|---|---|---|---|---|"]
    for ref, f in sh["formulas"].items():
        lines.append(f"| {ref} | {esc(f['label']['row'] or '')} | {esc(f['label']['col'] or '')} | "
                     f"{esc(f['cached'])} | `{esc(f['formula'])[:200]}` |")
    lines += ["", "</details>", ""]
    notes = [v for v in sh["text"].values() if len(v) > 40]
    if notes:
        lines += ["Notes in the sheet:", ""] + [f"- {esc(n)}" for n in notes] + [""]
with open(out, "w", encoding="utf-8") as fh:
    fh.write("\n".join(lines))
print(f"wrote {out}")
